//! Decode videos generated by ffmpeg during the test (skipped when ffmpeg is not installed).
use gothic_video::{DecodeOptions, FrameSync, Video, ffmpeg, generate_test_video, probe};
use std::path::PathBuf;
use std::process::Command;

fn tmp(name: &str) -> PathBuf {
    let dir = std::env::temp_dir().join(format!("gothic-video-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    dir.join(name)
}

macro_rules! need_ffmpeg {
    () => {
        if !ffmpeg::available() {
            eprintln!("skipped: ffmpeg/ffprobe not found (set GOTHIC_FFMPEG / GOTHIC_FFPROBE)");
            return;
        }
    };
}

#[test]
fn decodes_a_generated_video_with_audio() {
    need_ffmpeg!();
    let path = tmp("testsrc.avi");
    generate_test_video(&path, 2.0, 160, 120, 25, "mpeg4").unwrap();
    let info = probe(&path).unwrap();
    assert_eq!((info.width, info.height), (160, 120));
    assert!((info.fps - 25.0).abs() < 1e-6);
    assert!((info.duration - 2.0).abs() < 0.1, "{}", info.duration);
    assert_eq!(info.codec, "mpeg4");
    assert_eq!(info.audio.as_ref().unwrap().sample_rate, 48_000);

    let mut v = Video::open(&path, &DecodeOptions::default()).unwrap();
    let mut frames = Vec::new();
    while let Some(f) = v.video.next_blocking() {
        assert_eq!(f.rgba.len(), 160 * 120 * 4);
        frames.push((f.index, f.pts));
    }
    assert!(v.video.is_finished());
    assert_eq!(frames.len(), 50);
    assert_eq!(frames[25], (25, 1.0));

    // Audio: ~2 s of stereo 48 kHz, a sine with real amplitude.
    let buf = v.audio.as_ref().unwrap().buffer.clone();
    let mut total = 0usize;
    let mut peak = 0.0f32;
    let mut chunk = vec![0.0f32; 4096];
    while let Some(n) = buf.pop(&mut chunk) {
        if buf.buffered() == 0 && !buf.is_finished() {
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
        total += n;
        peak = chunk[..n].iter().fold(peak, |m, s| m.max(s.abs()));
        if total > 48_000 * 2 * 4 {
            panic!("audio does not end");
        }
    }
    let seconds = buf.position();
    assert!((1.9..2.3).contains(&seconds), "{seconds} s of audio");
    assert!(peak > 0.05, "sine audible, peak {peak}");
}

#[test]
fn colours_survive_decoding() {
    need_ffmpeg!();
    let path = tmp("red.mkv");
    let out = Command::new(ffmpeg::ffmpeg())
        .args([
            "-v",
            "error",
            "-y",
            "-f",
            "lavfi",
            "-i",
            "color=c=0xff0000:size=64x48:rate=10",
            "-t",
            "1",
            "-c:v",
            "ffv1",
            "-pix_fmt",
            "bgr0",
        ])
        .arg(&path)
        .output()
        .unwrap();
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    let mut v = Video::open(&path, &DecodeOptions::default()).unwrap();
    assert!(v.audio.is_none());
    let f = v.video.next_blocking().unwrap();
    // lavfi's colour source rounds through YUV: allow a few levels.
    let red = |p: &[u8]| p[0] >= 250 && p[1] <= 4 && p[2] <= 4 && p[3] == 255;
    assert!(f.rgba.chunks(4).all(red), "{:?}", &f.rgba[..4]);
    let mut n = 1;
    while v.video.next_blocking().is_some() {
        n += 1;
    }
    assert_eq!(n, 10);
}

#[test]
fn downscales_and_syncs() {
    need_ffmpeg!();
    let path = tmp("big.avi");
    generate_test_video(&path, 1.0, 320, 240, 30, "mpeg4").unwrap();
    let opts = DecodeOptions {
        max_width: Some(160),
        audio: false,
        ..DecodeOptions::default()
    };
    let mut v = Video::open(&path, &opts).unwrap();
    assert!(v.audio.is_none());
    assert_eq!((v.video.width, v.video.height), (160, 120));
    // Play at 10 Hz ticks: every third frame is shown, the others dropped as late.
    let mut sync = FrameSync::default();
    let mut shown = Vec::new();
    for tick in 0..=10 {
        let t = f64::from(tick) * 0.1;
        // Wait until the decoder has caught up for a deterministic test.
        let mut next = || v.video.next_blocking();
        if let Some(f) = sync.advance(t, &mut next) {
            shown.push(f.index);
        }
    }
    // t = 1.0: the last frame (29, due at 0.967) closes the run.
    assert_eq!(shown, [0, 3, 6, 9, 12, 15, 18, 21, 24, 27, 29]);
    assert!(sync.dropped >= 18, "{}", sync.dropped);
}

#[test]
fn bink_is_gated_on_the_decoder() {
    need_ffmpeg!();
    assert_eq!(ffmpeg::supports_bink(), ffmpeg::has_decoder("binkvideo"));
    // Not a real Bink file: probing fails with an error instead of panicking or hanging.
    let path = tmp("fake.bik");
    std::fs::write(&path, b"BIKi\0\0\0\0garbage").unwrap();
    assert!(probe(&path).is_err());
    assert!(Video::open(&tmp("missing.bik"), &DecodeOptions::default()).is_err());
}
